import {levels,cells,holes,setup,active,covered,accessible,destinations,move,complete,solve} from './engine.mjs';
const $=s=>document.querySelector(s), colors=['#557f79','#c67d57','#c9a75d','#739381','#9b7990','#668aa0','#b38563','#849457'];
let saved={};try{saved=JSON.parse(localStorage.getItem('screw-workshop-v1')||'{}')||{}}catch{}
let done=new Set(Array.isArray(saved.done)?saved.done.filter(n=>Number.isInteger(n)&&n>=0&&n<levels.length):[]),index=Number.isInteger(saved.level)&&saved.level>=0&&saved.level<levels.length?saved.level:0,state,history=[],selected=null,hinted=null,fallTimer=null;
function persist(){try{localStorage.setItem('screw-workshop-v1',JSON.stringify({level:index,done:[...done]}))}catch{}}
function start(i){clearTimeout(fallTimer);index=i;state=setup(levels[i]);history=[];selected=null;hinted=null;persist();render();say(levels[i].tip)}
function say(t){$('#message').textContent=t}
function pos(el,h){el.style.left=cells[h].x/350*100+'%';el.style.top=cells[h].y/430*100+'%'}
function render(falling=[]){const l=levels[index],board=$('#board');board.replaceChildren();$('#number').textContent=`PUZZLE ${String(index+1).padStart(2,'0')} / ${levels.length}`;$('#name').textContent=l.name;$('#moves').textContent=`${state.moves} ${state.moves===1?'move':'moves'}`;$('#remaining').textContent=`${l.plates.filter((_,i)=>active(l,state,i)).length} plates left`;$('#undo').disabled=!history.length;
 const avail=destinations(l,state);for(const h of holes(l)){if(covered(l,state,h))continue;const b=document.createElement('button');b.className='hole'+(selected!==null&&avail.includes(h)?' target':'');pos(b,h);b.style.zIndex=0;b.setAttribute('aria-label',`${h>=25?'Spare':'Board'} hole ${h+1}${avail.includes(h)?', empty':', occupied'}`);b.disabled=!avail.includes(h);b.onclick=()=>place(h);board.append(b)}
 const label=document.createElement('div');label.className='storage-label';label.textContent='TWO SPARE HOLES · MAKE ROOM';board.append(label);
 l.plates.forEach((pair,p)=>{if(!active(l,state,p)&&!falling.includes(p))return;const a=cells[pair[0]],b=cells[pair[1]],el=document.createElement('div');el.className='plate'+(falling.includes(p)?' falling':'');el.style.cssText=`left:${(Math.min(a.x,b.x)-23)/350*100}%;top:${(Math.min(a.y,b.y)-23)/430*100}%;width:${(Math.abs(a.x-b.x)+46)/350*100}%;height:${(Math.abs(a.y-b.y)+46)/430*100}%;--color:${colors[p%colors.length]};z-index:${p*2+1}`;board.append(el)});
 state.positions.forEach((h,b)=>{if(!accessible(l,state,b))return;const el=document.createElement('button');el.className='bolt'+(state.removed&(1<<b)?' parked':'')+(selected===b?' selected':'');pos(el,h);el.style.zIndex=state.removed&(1<<b)?30:Math.floor(b/2)*2+2;el.setAttribute('aria-label',`Screw ${b+1}${state.removed&(1<<b)?', parked':`, plate ${Math.floor(b/2)+1}`}`);el.setAttribute('aria-pressed',selected===b);el.onclick=()=>select(b);board.append(el)});
 const win=$('#win');win.hidden=!complete(l,state);if(!win.hidden){done.add(index);persist();win.innerHTML=`<span class="complete-mark">✓</span><h3>${index===levels.length-1?'A job well done.':'Nicely undone.'}</h3><p>${index===levels.length-1?'That’s the last puzzle. Nothing to claim, nothing to keep up with. Come back whenever you like.':`All plates cleared in ${state.moves} moves. A good place for a breather, or one more puzzle.`}</p><button class="primary" id="next">${index===levels.length-1?'Choose a puzzle':'Next puzzle →'}</button>`;$('#next').onclick=()=>index===levels.length-1?showLevels():start(index+1)}
}
function select(b){if(complete(levels[index],state))return;selected=selected===b?null:b;hinted=null;render();say(selected===null?'Screw put back. Choose another when you’re ready.':destinations(levels[index],state).length?'Now tap a glowing empty hole. Tap this screw again to cancel.':'No empty holes. Undo a move to make room.');}
function place(h){if(selected===null){say('First tap an exposed silver screw, then an empty hole.');return}const l=levels[index],next=move(l,state,selected,h);if(!next){say('That hole is covered or occupied. Choose a glowing empty hole.');return}const falling=l.plates.map((_,i)=>i).filter(i=>active(l,state,i)&&!active(l,next,i));history.push(structuredClone(state));state=next;selected=null;hinted=null;render(falling);clearTimeout(fallTimer);if(falling.length)fallTimer=setTimeout(()=>render(),600);if(complete(l,state))say('Board clear. Take a moment—you earned it.');else if(!destinations(l,state).length)say('No room left. Undo, then try freeing both screws from one plate.');else say(falling.length?'There it goes. Newly uncovered holes are yours to use.':'Good turn. Free both screws from a plate to let it fall.');}
$('#undo').onclick=()=>{if(!history.length)return;clearTimeout(fallTimer);state=history.pop();selected=null;hinted=null;render();say('One step back. Try another way.');};
function openDialog(title,html){$('#dialogtitle').textContent=title;$('#dialogbody').innerHTML=html;$('#dialog').showModal()}
$('#close').onclick=()=>$('#dialog').close();$('#dialog').addEventListener('click',e=>{if(e.target===$('#dialog')){const r=e.target.getBoundingClientRect();if(e.clientX<r.left||e.clientX>r.right||e.clientY<r.top||e.clientY>r.bottom)e.target.close()}});
$('#restart').onclick=()=>{if(!state.moves){start(index);return}openDialog('A fresh start?','<p>Restart this puzzle? Your other completed puzzles stay saved.</p><button class="primary" id="confirmrestart">Restart puzzle</button>');$('#confirmrestart').onclick=()=>{$('#dialog').close();start(index)}};
$('#hint').onclick=()=>{const path=solve(levels[index],state);if(!path){say('This position has no solution. Undo a move, then ask for a hint again.');return}if(!path.length){say('You’ve already cleared this puzzle.');return}selected=path[0];hinted=selected;render();say(`Try screw ${selected+1} (highlighted), then any glowing hole. This move keeps a solution open.`)};
function showLevels(){openDialog('Pick a puzzle',`<p>Ten finite puzzles. All available from the start.</p><div class="levelgrid">${levels.map((l,i)=>`<button data-level="${i}">${String(i+1).padStart(2,'0')} · ${l.name}<small>${done.has(i)?'✓ Completed':i===index?'Currently playing':'Ready whenever you are'}</small></button>`).join('')}</div>`);document.querySelectorAll('[data-level]').forEach(b=>b.onclick=()=>{$('#dialog').close();start(+b.dataset.level)})}$('#levels').onclick=showLevels;
$('#help').onclick=()=>openDialog('A turn at a time.','<ol><li>Tap an exposed silver screw, then an empty hole with a glowing ring.</li><li>Remove both screws from a plate and it falls away, uncovering more holes.</li><li>Upper plates can hide lower screws. Covered holes can’t receive screws.</li><li>Parked screws stay on the board. Clear every plate—not every screw.</li></ol><p>Only two spare holes to start. Work on one plate at a time. Undo and hints are always free.</p><p>No ads, purchases, timers, streaks, or random prizes. Progress is saved only in this browser.</p>');
$('#install').onclick=()=>openDialog('Keep the workshop handy.','<p>On iPhone, open this link in <strong>Safari</strong>, tap <strong>Share</strong>, then <strong>Add to Home Screen</strong>. You may need to scroll down the Share menu.</p><p>This is a web game, not an App Store download. An internet connection and your site access may be needed to open it. Completed puzzles are saved in this browser; clearing browser data removes that progress.</p>');
start(index);
